"""Adds the Rotina.ai native alarm to the Android project generated by `npx cap add android`.

Run from android-app/ after `npx cap add android`:
  - copies the Java sources (alarm + MainActivity) and resources (icons, splash)
  - adds permissions and alarm components to AndroidManifest.xml
  - signs the APK with the key from the GitHub secret (same key = updates install over the previous version)
"""
import os
import re
import shutil
import sys

ROOT = os.path.dirname(os.path.abspath(__file__))
APP = os.path.join(ROOT, 'android', 'app')
MAIN = os.path.join(APP, 'src', 'main')


def copy_tree(src, dst):
    for base, _dirs, files in os.walk(src):
        rel = os.path.relpath(base, src)
        target = os.path.join(dst, rel)
        os.makedirs(target, exist_ok=True)
        for f in files:
            shutil.copy2(os.path.join(base, f), os.path.join(target, f))


# 1) Java sources: replace the generated MainActivity and add the alarm package
java_dst = os.path.join(MAIN, 'java')
for base, _dirs, files in os.walk(java_dst):
    for f in files:
        if f == 'MainActivity.java':
            os.remove(os.path.join(base, f))
copy_tree(os.path.join(ROOT, 'native', 'java'), java_dst)

# 2) Resources: app icon + splash (remove Capacitor's default splash images)
res = os.path.join(MAIN, 'res')
for d in os.listdir(res):
    p = os.path.join(res, d)
    if d.startswith('drawable') and os.path.isdir(p):
        for f in os.listdir(p):
            if f.startswith('splash'):
                os.remove(os.path.join(p, f))
copy_tree(os.path.join(ROOT, 'native', 'res'), res)
bg = os.path.join(res, 'values', 'ic_launcher_background.xml')
if os.path.exists(bg):
    with open(bg, encoding='utf-8') as fh:
        s = fh.read()
    s = re.sub(r'(<color name="ic_launcher_background">)[^<]*(</color>)', r'\g<1>#8C7A6B\g<2>', s)
    with open(bg, 'w', encoding='utf-8') as fh:
        fh.write(s)

# 3) Manifest: permissions + alarm components
manifest_path = os.path.join(MAIN, 'AndroidManifest.xml')
with open(manifest_path, encoding='utf-8') as fh:
    manifest = fh.read()

permissions = [
    'android.permission.POST_NOTIFICATIONS',
    'android.permission.USE_EXACT_ALARM',
    'android.permission.RECEIVE_BOOT_COMPLETED',
    'android.permission.WAKE_LOCK',
    'android.permission.VIBRATE',
    'android.permission.FOREGROUND_SERVICE',
    'android.permission.FOREGROUND_SERVICE_MEDIA_PLAYBACK',
    'android.permission.USE_FULL_SCREEN_INTENT',
    'android.permission.SYSTEM_ALERT_WINDOW',
    'android.permission.REQUEST_IGNORE_BATTERY_OPTIMIZATIONS',
    'android.permission.ACCESS_NOTIFICATION_POLICY',
]
perm_xml = ''.join(
    f'    <uses-permission android:name="{p}" />\n' for p in permissions if p not in manifest
)
perm_xml += '    <uses-permission android:name="android.permission.SCHEDULE_EXACT_ALARM" android:maxSdkVersion="32" />\n'
manifest = manifest.replace('<application', perm_xml + '\n    <application', 1)

components = '''
        <!-- Rotina.ai native alarm -->
        <receiver android:name=".alarm.AlarmReceiver" android:exported="true">
            <intent-filter>
                <action android:name="android.intent.action.BOOT_COMPLETED" />
                <action android:name="android.intent.action.LOCKED_BOOT_COMPLETED" />
                <action android:name="android.intent.action.MY_PACKAGE_REPLACED" />
                <action android:name="android.intent.action.TIME_SET" />
                <action android:name="android.intent.action.TIMEZONE_CHANGED" />
                <action android:name="android.app.action.SCHEDULE_EXACT_ALARM_PERMISSION_STATE_CHANGED" />
            </intent-filter>
        </receiver>
        <receiver android:name=".alarm.ActionReceiver" android:exported="false" />
        <service
            android:name=".alarm.AlarmService"
            android:exported="false"
            android:foregroundServiceType="mediaPlayback" />
        <activity
            android:name=".alarm.AlarmActivity"
            android:exported="false"
            android:excludeFromRecents="true"
            android:launchMode="singleInstance"
            android:showWhenLocked="true"
            android:turnScreenOn="true"
            android:taskAffinity="br.com.rotinaai.app.alarm"
            android:theme="@android:style/Theme.DeviceDefault.NoActionBar.Fullscreen" />
'''
manifest = manifest.replace('</application>', components + '    </application>', 1)
with open(manifest_path, 'w', encoding='utf-8') as fh:
    fh.write(manifest)

# 4) Signing + version
gradle_path = os.path.join(APP, 'build.gradle')
with open(gradle_path, encoding='utf-8') as fh:
    gradle = fh.read()

run_number = int(os.environ.get('GITHUB_RUN_NUMBER', '1'))
gradle = re.sub(r'versionCode\s+\d+', f'versionCode {run_number}', gradle, count=1)
gradle = re.sub(r'versionName\s+"[^"]*"', f'versionName "1.0.{run_number}"', gradle, count=1)

# Key comes from the GitHub secret ANDROID_KEYSTORE_BASE64 (decoded by the workflow); never committed
keystore = os.environ.get('KEYSTORE_PATH', '')
password = os.environ.get('KEYSTORE_PASSWORD', '')
alias = os.environ.get('KEYSTORE_ALIAS', 'rotinaai')
if not keystore or not os.path.exists(keystore):
    sys.exit('KEYSTORE_PATH not set')
signing = f'''
    signingConfigs {{
        rotina {{
            storeFile file("{keystore}")
            storePassword System.getenv("KEYSTORE_PASSWORD")
            keyAlias "{alias}"
            keyPassword System.getenv("KEYSTORE_PASSWORD")
        }}
    }}
'''
if 'signingConfigs' not in gradle:
    gradle = gradle.replace('    buildTypes {', signing + '    buildTypes {', 1)
gradle = re.sub(r'(buildTypes\s*\{\s*release\s*\{)', r'\1\n            signingConfig signingConfigs.rotina', gradle, count=1)
with open(gradle_path, 'w', encoding='utf-8') as fh:
    fh.write(gradle)

if 'signingConfig signingConfigs.rotina' not in gradle:
    sys.exit('Could not add the signing config to build.gradle')
print('Android project patched: alarm, icons, permissions and signing.')
